import{_ as d,c as a,o as r,a2 as e}from"./chunks/framework.CHomSxuB.js";const c=JSON.parse('{"title":"7. 模拟盘执行线：卖出口径三票裁决与双点闭环","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/7-模拟盘执行线.md","filePath":"A股量化验证/7-模拟盘执行线.md"}'),o={name:"A股量化验证/7-模拟盘执行线.md"};function n(h,t,l,i,s,p){return r(),a("div",null,t[0]||(t[0]=[e('<h1 id="_7-模拟盘执行线-卖出口径三票裁决与双点闭环" tabindex="-1">7. 模拟盘执行线：卖出口径三票裁决与双点闭环 <a class="header-anchor" href="#_7-模拟盘执行线-卖出口径三票裁决与双点闭环" aria-label="Permalink to &quot;7. 模拟盘执行线：卖出口径三票裁决与双点闭环&quot;">​</a></h1><blockquote><p>研究线（Step 1→4）回答&quot;信号有没有 edge&quot;，执行线回答&quot;edge 能不能装进一个按真实规则运转的小账户&quot;。 2026-09-02，卖出口径经三轮回测裁决（E1/E2/E3），结论收敛为三个字——<strong>不折腾</strong>：不装止损、不走封板顺延、卖出统一放次日尾盘。 裁决日期：2026-09-02 ｜ 状态：🔴 V1.0 冻结运行中（2026-09-03 起首个验证日）</p></blockquote><p><a href="/A股量化验证/">返回 A股量化验证 首页</a></p><hr><h2 id="一、执行线在补什么" tabindex="-1">一、执行线在补什么 <a class="header-anchor" href="#一、执行线在补什么" aria-label="Permalink to &quot;一、执行线在补什么&quot;">​</a></h2><p>Step 4 前向追踪用<strong>理论价</strong>（信号日收盘价买入 → T+1 收盘卖出）判断信号有没有 edge， 但&quot;收盘价&quot;在真实世界排不进单——只能市价/限价成交。模拟盘就是补上这段的执行器：</p><ul><li>候选：前一日收盘涨停池，经机械漏斗过滤（含现金预检），开盘后 09:31 市价买入；开盘 ≥ 昨收 × 1.095 视为排不进单 → 弃单（与 Step 4 一字闸同值）；</li><li>卖出：次交易日 <strong>14:57 尾盘市价清仓 ≈ 当日收盘价</strong>（A 股 T+1，最早可卖日）；</li><li>摩擦：系统实扣佣金等（低于研究线假设的 0.35%，属偏保守侧）；连亏 ≥ 3 笔熔断停手；</li><li>超额基准：对标中证 1000（000852），口径与 Step 4 相同。</li></ul><p>买入规则沿用冻结纪律。执行线自己只多了一个待裁决问题——<strong>卖出时刻要不要&quot;优化&quot;</strong>。</p><h2 id="二、要裁决的问题" tabindex="-1">二、要裁决的问题 <a class="header-anchor" href="#二、要裁决的问题" aria-label="Permalink to &quot;二、要裁决的问题&quot;">​</a></h2><p>&quot;次日卖出&quot;常见的优化有四类：破位止损（Kill）、封板顺延持有（Lock）、盘中择时（Time-out）、尾盘统一卖（EOD）。 直觉上&quot;动态卖出&quot;应该加分，2026-09-02 用三组数据逐条验证 （口径：T 日涨停收盘买入 → T+1 卖出，扣双边摩擦，与 Step 4 Ev 同构）：</p><h3 id="e1-·-历史真成交-5-笔-开盘卖-vs-收盘卖-n-5-2026-09-02" tabindex="-1">E1 · 历史真成交 5 笔：开盘卖 vs 收盘卖（n=5，2026-09-02） <a class="header-anchor" href="#e1-·-历史真成交-5-笔-开盘卖-vs-收盘卖-n-5-2026-09-02" aria-label="Permalink to &quot;E1 · 历史真成交 5 笔：开盘卖 vs 收盘卖（n=5，2026-09-02）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卖出点</th><th>平均收益</th><th>胜率</th></tr></thead><tbody><tr><td>T+1 收盘卖</td><td>+10.46%</td><td>5/5</td></tr><tr><td>T+1 开盘卖</td><td>+8.24%</td><td>4/5</td></tr></tbody></table><p>差约 +2.2pp/笔，其中约九成来自单笔&quot;低开高走大阳&quot;；反向证据同样存在 （高开低走的一笔，开盘卖保住 +13.21%，收盘卖只剩 +3.77%）。 结构规律：T+1 收阳 → 收盘卖优（4/4）；高开低走 → 开盘卖优（1/1）。<strong>n=5 不足以裁决，仅作方向参考。</strong></p><h3 id="e2-·-卖出状态机全量裁决-16-745-样本-244-交易日-全涨停生态-2026-09-02" tabindex="-1">E2 · 卖出状态机全量裁决（16,745 样本 / 244 交易日，全涨停生态，2026-09-02） <a class="header-anchor" href="#e2-·-卖出状态机全量裁决-16-745-样本-244-交易日-全涨停生态-2026-09-02" aria-label="Permalink to &quot;E2 · 卖出状态机全量裁决（16,745 样本 / 244 交易日，全涨停生态，2026-09-02）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>相对&quot;静态收盘卖&quot;贡献</th><th>结论</th></tr></thead><tbody><tr><td>组合状态机</td><td>+0.80pp</td><td>增量<strong>全部</strong>来自 Lock</td></tr><tr><td>其中：封板顺延（Lock）</td><td>+0.96pp（顺延样本 3,061）</td><td>唯一正贡献来源</td></tr><tr><td>单独装止损（Kill-Loss）</td><td><strong>−0.16pp</strong></td><td>止损系统性卖在坑里</td></tr><tr><td>尾盘统一卖（EOD）</td><td>≈ 0</td><td>与静态收盘卖同价，纯纪律</td></tr></tbody></table><p>Kill 为什么是负的？A 股涨停股 T+1 深跌多为<strong>低开修复型</strong>：开盘砸出坑、盘中回升， 固定时点（尾盘）卖出恰好躲过坑底；止损则把单子精确成交在坑里 （细分：KILL_OPEN n=396、KILL_INTRADAY n=3,744，两组均为负）。</p><h3 id="e3-·-lock-专项裁决-全历史-t-1-收盘仍封板样本-n-3-158-2026-09-02" tabindex="-1">E3 · Lock 专项裁决（全历史 T+1 收盘仍封板样本 n=3,158，2026-09-02） <a class="header-anchor" href="#e3-·-lock-专项裁决-全历史-t-1-收盘仍封板样本-n-3-158-2026-09-02" aria-label="Permalink to &quot;E3 · Lock 专项裁决（全历史 T+1 收盘仍封板样本 n=3,158，2026-09-02）&quot;">​</a></h3><p>10cm 首板子集（n=1,651）四种卖出路径的全程收益：</p><table tabindex="0"><thead><tr><th>路径</th><th>收益</th></tr></thead><tbody><tr><td>A · T+1 收盘卖</td><td>+10.04%</td></tr><tr><td>C · 固定多持 1 天</td><td>+12.64%</td></tr><tr><td>Bc · 一路持有到断板日收盘</td><td>+14.98%</td></tr><tr><td>Bo · 断板日开盘卖</td><td>+18.21%（断板日约 40% 低开 → 偏乐观基准，Bc 才是可执行基准）</td></tr></tbody></table><p>顺延增量（Bc − A）<strong>均值 +4.94pp，中位数仅 +1.30pp</strong>（p25 −3.3% / p75 +8.0%）→ 增量极右偏， 由约 14% 走出 ≥3 板的样本撑起；最差 5% 增量 −0.33pp → 无大亏尾，但持仓周期从 1 天拉长到 ~2.5 天。</p><p>定性：Lock 是干净的正期望，但本质是一笔<strong>用 25% 概率少赚 3.3pp、换 14% 概率多赚 8pp+ 的右尾赌局</strong>， 且必须无条件持有到断板才成立（中途止损会摧毁其收益结构）——属策略级变更，不是&quot;卖出触发器&quot;。</p><h2 id="三、三票定稿-2026-09-02-与-v1-0-冻结" tabindex="-1">三、三票定稿（2026-09-02）与 V1.0 冻结 <a class="header-anchor" href="#三、三票定稿-2026-09-02-与-v1-0-冻结" aria-label="Permalink to &quot;三、三票定稿（2026-09-02）与 V1.0 冻结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>票</th><th>依据</th></tr></thead><tbody><tr><td>卖出点 = 次日尾盘（EOD / 14:57）</td><td>✅ 装</td><td>与静态收盘卖等价（E2）；与 Step 4 理论口径同构、账本可对账；顺带拆成独立结算任务</td></tr><tr><td>止损（Kill-Loss）</td><td>❌ 不装</td><td>E2：−0.16pp，保费视角不成立</td></tr><tr><td>封板顺延（Lock）</td><td>📦 归档</td><td>E3：正期望但极右偏 + 持仓周期变更；要试必须走预注册，禁止直接并入</td></tr></tbody></table><p><strong>执行线 V1.0 就此冻结</strong>（2026-09-03 起运行）：09:31 决策买入 + 14:57 尾盘结算，卖出无 Kill、无 Lock。</p><p>附带一项工程裁决：候选<strong>决策窗深度取 top5 已足够</strong>（244 交易日口径、机械排序：首个可成交票 rank1 占 86.8%、 rank2 占 11.5%、rank3 占 1.2%、rank4 占 0.4%，<strong>rank≥5 从未被需要</strong>）→ top5 与无限深递补全等，5 不是拍脑袋定的。</p><h2 id="四、与研究线的分工-防口径混用" tabindex="-1">四、与研究线的分工（防口径混用） <a class="header-anchor" href="#四、与研究线的分工-防口径混用" aria-label="Permalink to &quot;四、与研究线的分工（防口径混用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>研究线 Step 4</th><th>执行线模拟盘</th></tr></thead><tbody><tr><td>回答</td><td>信号有没有 edge</td><td>edge 能不能落地进规则账户</td></tr><tr><td>买入</td><td>信号日收盘价（理论排板）</td><td>执行日 09:31 市价（真实可成交报价）</td></tr><tr><td>卖出</td><td>T+1 收盘价（理论）</td><td>T+1 14:57 尾盘 ≈ 收盘价</td></tr><tr><td>两者关系</td><td>判据线</td><td>收益通常低于理论值（早盘买点更差），这正是&quot;回测 edge → 实盘折价&quot;要量化的部分</td></tr></tbody></table><h2 id="五、已知局限-诚实项" tabindex="-1">五、已知局限（诚实项） <a class="header-anchor" href="#五、已知局限-诚实项" aria-label="Permalink to &quot;五、已知局限（诚实项）&quot;">​</a></h2><ul><li>E1 仅 n=5，只作方向不作证据；E2/E3 为全量回测，仍是历史口径；</li><li>模拟盘为撮合模拟，非真实资金——真实世界的滑点、流动性、执行情绪不在模型里；</li><li>Lock 归档 ≠ 证伪：它的正期望是干净的，只是收益结构（右尾）+ 持仓周期不符合当前&quot;短打 + 快速攒样本&quot;的定位。</li></ul><hr><p><strong>互链</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · 上一篇：<a href="/A股量化验证/6-数据洁净度审计.html">6. 数据洁净度审计</a></p>',31)]))}const b=d(o,[["render",n]]);export{c as __pageData,b as default};
